// FUNCTION: BFME2 0x0007BFC2 size=307 name=?Set@PlaneClass@@QAEXABVVector3@@00@Z evidence=N:ledger tier=B hypothesis:K
void PlaneClass::Set(const Vector3 &point1, const Vector3 &point2, const Vector3 &point3)
{
	Vector3::Cross_Product(point2 - point1, point3 - point1, &N);
	if (N != Vector3(0.0f, 0.0f, 0.0f)) {
		N.Normalize();
		D = (point1.X * N.X + N.Y * point1.Y) + point1.Z * N.Z;
	} else {
		N = Vector3(0.0f, 0.0f, 1.0f);
		D = 0.0f;
	}
}

